insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 1, 'lpgBlendProperties prints a basis beside each of the three properties it returns for KANO''s blend. Which pairing does it print?', '["Density on mass, latent heat on volume, molar mass on mole.", "Density on volume, latent heat on volume, molar mass on mass.", "Density on volume, latent heat on mass, molar mass on mole.", "Density on mole, latent heat on mass, molar mass on volume."]'::jsonb, 2, 'SECTION 25 prints KANO''s row as 557.4000 (volume), 397.7592 (mass) and 52.7681 (mole), and states: density blends on volume; latent heat per kilogram blends on mass; molar mass blends on moles. Each other pairing moves at least one property onto a basis the engine does not use for it.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 2, 'KANO''s blend is propane 0.35 and butane 0.65 by liquid volume, on the typical figures. What latent heat does the engine return for it?', '["397.7592 kJ/kg", "399.0000 kJ/kg", "399.6821 kJ/kg", "385 kJ/kg"]'::jsonb, 0, 'The KANO row prints latentHeatKJkg 397.7592 on mass. 399.0000 kJ/kg is KANO''s latent heat averaged on the volume fractions, which SECTION 25 prints as 1.2408 kJ/kg from the engine''s; 399.6821 kJ/kg is the studio opening blend; 385 kJ/kg is n-butane''s typical row in LPG_REFERENCE.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 3, 'KANO''s blend is typed as propane 0.35 by liquid volume. What propane mass fraction does lpgBlendProperties print for it?', '["0.3671", "0.3190", "0.6810", "0.6329"]'::jsonb, 1, 'The KANO row prints a propane mass fraction of 0.3190 and a butane mass fraction of 0.6810. 0.3671 and 0.6329 are the studio opening blend''s propane and butane mass fractions.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 4, 'What molar mass does the engine return for KANO''s blend, and on which basis?', '["52.0456 kg/kmol, on mole", "52.7681 kg/kmol, on mole", "52.7681 kg/kmol, on mass", "58.122 kg/kmol, on mole"]'::jsonb, 1, 'The KANO row prints molarMassKgKmol 52.7681 (mole). 52.0456 kg/kmol is the studio opening blend''s; 58.122 kg/kmol is n-butane''s own molar mass in LPG_REFERENCE; and the molar mass blends on moles, so a mass basis is wrong for it.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 5, 'KANO''s blend is run with butane''s latent heat left blank. What does lpgBlendProperties return?', '["A latent heat on propane alone, and the density 557.4000 kg/m3", "A null latent heat, and the density still 557.4000 kg/m3", "A null latent heat and a null density for the blend", "REFUSED: A liquid density is required for every component; it is not assumed."]'::jsonb, 1, 'SECTION 25: with butane''s latent heat left blank the blend''s latent heat is null and its density still 557.4000 kg/m3, with the note "A property missing on any component is reported as missing for the blend. It is never averaged over the components that have it." The quoted refusal is the one for a blank butane liquid density.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 6, 'A butane liquid density left blank is put to lpgBlendProperties. What does the engine print?', '["REFUSED: A liquid density is required for every component; it is not assumed.", "REFUSED: A liquid density is required; it is not assumed.", "REFUSED: Every component needs a volume fraction.", "A null density, reported as missing for the blend."]'::jsonb, 0, 'SECTION 25''s probe table prints this refusal for the blank butane density. "A liquid density is required; it is not assumed." is lpgStorageSizing''s refusal for a vessel with no liquid density (SECTION 26), and "Every component needs a volume fraction." is the refusal for a blank butane volume fraction.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 7, 'lpgStorageSizing is called for KANO''s vessel with the fill limit left blank. What comes back?', '["The vessel sized at 0.85 on liquid_volume.", "REFUSED: The maximum fill ratio must lie between 0 and 1.", "REFUSED: Unknown fill ratio basis \"\". Use liquid_volume or water_capacity_mass.", "REFUSED: A maximum fill ratio is required and is not defaulted."]'::jsonb, 3, 'SECTION 26: the fill limit is required and has no default; the blank probe prints "REFUSED: A maximum fill ratio is required and is not defaulted. It is a code limit for the product and the vessel: LPG expands and a vessel filled liquid-full ruptures hydraulically." 0.85 is one of two illustrative limits typed for KANO, neither a code value.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 8, 'The fill ratio basis is OMITTED from the call for KANO''s vessel at a fill limit of 0.85. What does the engine do?', '["It takes water_capacity_mass, names it, and gives 62.9433 t usable.", "REFUSED: Unknown fill ratio basis \"\". Use liquid_volume or water_capacity_mass.", "It takes liquid_volume, names it, and gives 71.0685 t usable.", "It names the basis in missingInputs and gives usableTonnes null."]'::jsonb, 2, 'SECTION 26: omitted from the call, the engine takes liquid_volume and names it in its output: fillRatioBasis liquid_volume, usableTonnes 71.0685 at a fill limit of 0.85. The refusal is what a basis typed blank ('''') gets. 62.9433 t is the 0.42 limit on water_capacity_mass.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 9, 'KANO''s vessel is sized at a fill limit of 0.42 on water_capacity_mass. What usable LPG does the engine return?', '["35.1162 t", "71.0685 t", "62.9433 t", "27.8271 t"]'::jsonb, 2, 'The 0.42 water_capacity_mass row prints usableTonnes 62.9433. 35.1162 t is the same 0.42 read on the other basis, as a share of the liquid volume, and 27.8271 t is how far that reading sits below the filling density''s 62.9433 t. 71.0685 t is the 0.85 liquid_volume row.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 10, 'On the water-capacity basis, at what density does the engine weigh the vessel''s water capacity?', '["WATER_KG_M3, that is 999.1 kg/m3", "The blend''s 557.4000 kg/m3", "n-butane''s typical 584 kg/m3", "The studio blend''s 553.6000 kg/m3"]'::jsonb, 0, 'SECTION 26: on the water-capacity basis the engine weighs the water capacity at WATER_KG_M3 = 999.1 kg/m3. 557.4000 kg/m3 is KANO''s blend density, the liquid density the vessel rows use; 584 kg/m3 is n-butane''s typical row; 553.6000 kg/m3 is the studio opening blend.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 11, 'At the 0.85 liquid_volume fill, which reorder point and ullage at reorder does lpgStorageSizing print for KANO?', '["reorderAtTonnes 40.0000, ullageAtReorderTonnes 22.9433", "reorderAtTonnes 16.0000, ullageAtReorderTonnes 31.0685", "reorderAtTonnes 16.0000, ullageAtReorderTonnes 22.9433", "reorderAtTonnes 40.0000, ullageAtReorderTonnes 31.0685"]'::jsonb, 3, 'The 0.85 row prints reorderAtTonnes 40.0000 and ullageAtReorderTonnes 31.0685. 22.9433 is the 0.42 row''s ullage; 16.0000 is the safety stock, the reorder point the engine gives when the lead time is omitted from the call and takes the stated 0.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 12, 'KANO''s lead time is left blank ('''') at the 0.85 fill. What does lpgStorageSizing return?', '["missingInputs none, reorderAtTonnes 16.0000 from the safety stock alone", "lead time in missingInputs, reorderAtTonnes null, cover still 8.8840 days", "REFUSED on the lead time, with no cover and no reorder point given", "lead time in missingInputs, reorderAtTonnes 40.0000, cover 8.8840 days"]'::jsonb, 1, 'SECTION 26: a blank lead time is missing: missingInputs lead time; reorderAtTonnes null; deliveryFitsUllage no verdict; the cover (8.8840 days) does not depend on it and is still given. missingInputs none with a reorder point of 16.0000 is what the engine gives when the lead time is OMITTED and takes the stated 0.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 13, 'A filling density of 0.6 on water capacity is put to KANO''s vessel at the blend density. What does the engine print?', '["REFUSED: The maximum fill ratio must lie between 0 and 1.", "A usable volume larger than the 150 m3 vessel, with the vapour space printed below zero.", "REFUSED: At this density the filling density fills the vessel liquid-full. Check the limit and its basis.", "REFUSED: Unknown fill ratio basis \"weight\". Use liquid_volume or water_capacity_mass."]'::jsonb, 2, 'SECTION 26''s probe table prints the liquid-full refusal for this case. The between 0 and 1 refusal is the probe with a fill limit of 1; the unknown basis refusal is the basis typed as ''weight''.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 14, 'What vapour space does lpgStorageSizing leave in KANO''s 150 m3 vessel at the 0.42 water_capacity_mass limit?', '["37.0770 m3", "22.5000 m3", "112.9230 m3", "127.5000 m3"]'::jsonb, 0, 'The 0.42 row prints usableM3 112.9230 and vapourSpaceM3 37.0770; the digest states vapourSpaceM3 is the vessel less usableM3. 22.5000 m3 is the vapour space at the 0.85 liquid_volume fill, and 127.5000 m3 that row''s usable volume.'),
  ('gasvalue', 'advanced', 'module', 'm01-the-lpg-blend-and-the-vessel', 15, 'At the 0.85 fill, usableTonnes over the demand is printed as 8.8836, and the engine''s coverDays as 8.8840. What does the digest give as the reason?', '["The engine holds the 16.0000 t safety stock back from the cover.", "The engine takes the cover on the water capacity at 999.1 kg/m3.", "The engine adds the 3 day lead time before it divides.", "The engine reports coverDays rounded to three decimals."]'::jsonb, 3, 'SECTION 26''s rounding note: the engine reports coverDays to three decimals, so its cover prints with a final 0 at four decimals and can differ in the fourth decimal from usableTonnes over the demand. The digest''s rule is that coverDays is usableTonnes over the demand, with no safety stock, water weight or lead time in it.'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 1, 'Which term of KANO''s vaporizer duty does the engine print at 0.8368 of the duty?', '["Warm the liquid to boiling, 8.8472 kW", "Boil it, 71.8176 kW of the dutyKW 85.8215 kW", "Superheat the vapour, 5.1567 kW", "designDutyKW, 98.6948 kW"]'::jsonb, 1, 'SECTION 27''s term table prints Boil it at 71.8176 kW and 0.8368 of the duty. Warming the liquid is 8.8472 kW at 0.1031 and superheating is 5.1567 kW at 0.0601; designDutyKW 98.6948 kW carries no share.'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 2, 'KANO''s vaporizer takes 650 kg/h with a design margin of 15 percent. What design duty does the engine give?', '["85.8215 kW", "71.8176 kW", "8.8472 kW", "98.6948 kW"]'::jsonb, 3, 'designDutyKW is dutyKW times one plus the margin percent over 100, and SECTION 27 prints it as 98.6948 kW. 85.8215 kW is dutyKW before the margin, 71.8176 kW the boil term alone, and 8.8472 kW the warming term.'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 3, 'KANO''s vaporizer duty is asked for with the boiling point left blank. Which result comes back?', '["dutyKW 71.8176, with warming and superheat named as missing terms", "dutyKW 85.8215, on butane''s typical boiling point of -0.5 C", "REFUSED: A latent heat of vaporisation is required; it is a property of the product and is not assumed.", "designDutyKW 98.6948, with the boiling point taken at 38 C"]'::jsonb, 0, 'SECTION 27: with the boiling point left blank the engine gives the boil alone: dutyKW 71.8176, missingTerms Warm the liquid to boiling; Superheat the vapour, and a note that the duty is a floor. The latent heat refusal is the probe with no latent heat.'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 4, 'n-butane''s atmospheric boiling point of -0.5 C from LPG_REFERENCE is typed for KANO''s vaporizer, with the liquid entering at 18 C. What does the engine print?', '["dutyKW 71.8176, the boil alone, with the engine''s note that the duty is a floor.", "REFUSED: The vapour leaves at 30 C, below the boiling point given (38 C), so it would condense.", "REFUSED: The liquid enters at 18 C, above the boiling point given (-0.5 C).", "A duty whose warming term is printed below zero kW."]'::jsonb, 2, 'SECTION 27 prints the refusal in full: "The liquid enters at 18 C, above the boiling point given (-0.5 C). A liquid above its boiling point is not liquid: give the boiling point at the vaporizer''s operating pressure." The boil alone is the blank boiling point; the condense refusal is the outlet at 30 C.'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 5, 'KANO''s vaporizer is given a design margin of -5 percent. What comes back?', '["designDutyKW equal to dutyKW, 85.8215 kW, the margin taken as zero.", "A design duty below the 85.8215 kW dutyKW.", "REFUSED: A latent heat of vaporisation is required.", "REFUSED: The design margin cannot be negative."]'::jsonb, 3, 'SECTION 27''s probe table prints "REFUSED: The design margin cannot be negative." for a margin of -5 percent. The margin is refused; it is neither taken as zero nor applied.'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 6, 'How does vaporizerDuty form its Boil it term, before dividing by KJ_PER_KWH?', '["The mass flow times the vapour heat capacity times (outlet less boiling point).", "The mass flow times the latent heat.", "The mass flow times the liquid heat capacity times (boiling point less inlet).", "dutyKW times one plus the margin percent over 100."]'::jsonb, 1, 'SECTION 27: boil it is the mass flow times the latent heat. The heat capacity products are the superheat and warming terms, and dutyKW times one plus the margin percent over 100 is designDutyKW.'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 7, 'On how many positions does the engine run KANO''s carousel queue, from 18 positions each available 0.92 of the time?', '["17, 16.56 rounded to the nearest", "18, every position on the carousel", "16, the floor of the 16.56 positions working", "13, minimumPositionsForThroughput"]'::jsonb, 2, 'SECTION 28 prints effectivePositions 16.5600 and queuePositions 16: the queue runs on the positions wholly working, the floor of the positions times the availability. 17 is the positions rounded to the nearest whole one, which the digest names as the shortcut the engine does not take; 13 is minimumPositionsForThroughput.'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 8, 'KANO''s carousel prints throughputCapacityPerDay 4516.3600. Which positions figure does the engine use for it?', '["The unrounded 16.56 of effectivePositions", "The 16 working positions the queue itself runs on", "The 17 positions rounded to the nearest", "The 13 positions of minimumPositionsForThroughput"]'::jsonb, 0, 'The positionRoundingNote reads: "The queue is computed on 16 working positions, rounded down from 16.56, because a queue has a whole number of servers. The throughput capacity below uses the unrounded figure."'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 9, 'KANO''s carousel prints a queue utilisation of 0.7333 beside an availability of 0.92. What does the engine''s note say about the two?', '["Availability is how busy the working positions are; utilisation reduces the positions that are working.", "They are one number read two ways, so a plant may be sized on either alone.", "Utilisation is availability applied to the 18 positions, read as a share.", "Availability reduces the positions that are working; utilisation is how busy the working ones are."]'::jsonb, 3, 'The note: "Availability reduces the positions that are working; utilisation is how busy the working ones are. They are different numbers and a plant sized on one alone comes up short."'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 10, 'KANO''s carousel is run at availability 1 on 17 positions. What average wait does the digest print?', '["0.0450 minutes", "0.0912 minutes", "0.0222 minutes", "0.9850 minutes"]'::jsonb, 0, 'The whole-positions table prints 0.0912 minutes on 16, 0.0450 minutes on 17 and 0.0222 minutes on 18. 0.9850 minutes is the studio''s opening carousel.'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 11, 'bottlingPlant is given one position at availability 0.4. What does it print?', '["REFUSED: Only 0.4 positions are working on average: fewer than one.", "REFUSED: Shift hours must be positive and availability must lie in (0, 1].", "REFUSED: Demand, fill time and a position count are required and must be positive.", "A queue on one position, since a queue has a whole number of servers."]'::jsonb, 0, 'SECTION 28''s probe table prints "REFUSED: Only 0.4 positions are working on average: fewer than one." for this case. The other two refusals are for blank shift hours or availability 1.2, and for no fill time.'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 12, 'Which two of the carousel probes print the same refusal?', '["Availability 1.2, and one position at availability 0.4", "No fill time, and shift hours left blank", "Shift hours left blank, and availability 1.2", "One position at availability 0.4, and no fill time"]'::jsonb, 2, 'SECTION 28 prints "REFUSED: Shift hours must be positive and availability must lie in (0, 1]." for both shift hours left blank ('''') and availability 1.2. One position at 0.4 and no fill time each print a refusal of their own.'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 13, 'Which field does assetFloat print as 7296.0000 for KANO''s cylinders?', '["spareCapacityUnits", "inCirculation", "fleetRequired", "sparesAllowance"]'::jsonb, 3, 'The KANO cylinders table prints inCirculation 91200.0000, sparesAllowance 7296.0000, fleetRequired 98496 and spareCapacityUnits 0.0000. The spares allowance is the assets in circulation times the spares fraction of 0.08.'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 14, 'KANO''s cylinder cycle is 28.5000 days. Which stage does assetFloat name as dominantStage, and at what share of the cycle?', '["At the plant, 0.0526", "At the customer, 0.8421", "In transit back, 0.0526", "On station, 0.5556"]'::jsonb, 1, 'The KANO cylinders table prints At the customer at 24 days and 0.8421 of the cycle, and dominantStage At the customer. The two transit stages and At the plant each print 0.0526; On station, 0.5556, is a stage of IBAFO''s trailers.'),
  ('gasvalue', 'advanced', 'module', 'm02-vaporizer-carousel-and-float', 15, 'KANO''s cycle is put to assetFloat with the At the customer stage left blank. What does the engine print?', '["A fleet sized on the other stages, with that stage in missingInputs.", "REFUSED: At least one cycle stage with a duration is required.", "REFUSED: No duration for At the customer.", "REFUSED: The spares allowance cannot be negative."]'::jsonb, 2, 'SECTION 29 prints "REFUSED: No duration for At the customer. A stage left out shrinks the fleet by the assets in it, so the fleet is not sized without it." The at least one stage refusal is the probe with no stages; the spares refusal is a negative spares allowance.'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 1, 'What pressureBasis does lpgCng print on every CNG result?', '["absolute (bar(a))", "gauge (bar(g))", "absolute (psia)", "gauge plus atmosphere (bar)"]'::jsonb, 0, 'SECTION 30: every pressure in lpgCng is absolute, and the engine says so on every CNG result: pressureBasis "absolute (bar(a))".'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 2, 'Of the three IBAFO banks, which mass does gasMassInVessel print for the Mid bank at 250 bar(a)?', '["356.2099 kg", "425.6447 kg", "425.6293 kg", "448.1628 kg"]'::jsonb, 2, 'The Mid row prints massKg 425.6293 and idealMassKg 356.2099. 425.6447 kg is the mass for the gauge reading of 249 bar plus the atmosphere, 250.0130 bar(a); 448.1628 kg is the High bank.'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 3, 'IBAFO''s banks hold gas of specific gravity 0.62. Which Z does the engine give the bank at 230 bar(a)?', '["0.8369", "0.8584", "1.2224", "0.8181"]'::jsonb, 3, 'The Low row prints z 0.8181 and realVersusIdeal 1.2224. 0.8369 is the Mid bank''s Z and 0.8584 the High bank''s.'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 4, 'Every IBAFO bank prints realVersusIdeal above one. What does the digest say that shows?', '["Every bank holds less gas than the ideal gas law says.", "Every bank holds more gas than the ideal gas law says.", "Z is above one at these pressures, for every bank.", "The correlation is outside its range for every bank."]'::jsonb, 1, 'SECTION 30: at these pressures Z is below one, so every bank holds more gas than the ideal gas law says (realVersusIdeal above one). The three rows print correlationInRange true.'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 5, 'IBAFO''s three banks are all at 30 C. Which column of the bank table prints the same figure on all three?', '["ppr, at 5.3782", "z, at 0.8369", "tpr, at 1.5266", "realVersusIdeal, at 1.1949"]'::jsonb, 2, 'The bank table prints tpr 1.5266 on the Low, Mid and High rows. ppr, z and realVersusIdeal each print a different figure on each bank; 5.3782, 0.8369 and 1.1949 are the Mid bank''s.'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 6, 'In m = P V M over Z R T, what does gasMassInVessel take as M?', '["The gas''s specific gravity times the molar mass of air", "The specific gravity of 0.62 alone, as a ratio", "The molar mass of air, with the gravity put into Z", "The gas mass over the bank volume at 30 C"]'::jsonb, 0, 'SECTION 30: M is the gas''s molar mass, its specific gravity times the molar mass of air, in kg/kmol.'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 7, 'In what unit does the pressure P enter the mass equation in gasMassInVessel?', '["bar(a), as typed", "psia, as bar(a) times PSI_PER_BAR", "bar, as the gauge plus 1.013", "Pa, as bar(a) times 100000"]'::jsonb, 3, 'SECTION 30: P is the pressure in Pa (bar(a) times 100000). Every pressure in lpgCng is absolute.'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 8, 'An IBAFO bank reads 249 bar on its gauge, and 249 is typed straight into the engine as if absolute. What mass comes back?', '["425.6447 kg", "425.6293 kg", "424.4393 kg", "1.2054 kg"]'::jsonb, 2, 'The gauge table prints 424.4393 kg for the gauge reading typed as if absolute and 425.6447 kg for gauge plus atmosphere; 1.2054 kg is absolute minus gauge-as-absolute. 425.6293 kg is the Mid bank at 250 bar(a).'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 9, 'For the same 249 bar gauge reading, what pressure does the gauge plus atmosphere row give the engine?', '["249 bar(a)", "250 bar(a)", "250.0130 bar(a)", "1.0130 bar(a)"]'::jsonb, 2, 'The row labelled gauge plus atmosphere prints 250.0130 bar(a), the site''s atmosphere taken as 1.013 bar(a). The row for the gauge typed as if absolute prints 249, the difference row prints 1.0130, and 250 bar(a) is what the Mid bank is typed at.'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 10, 'What range does DAK_RANGE print for the Dranchuk-Abou-Kassem correlation?', '["ppr 0.2 to 30, tpr 1 to 3", "ppr 1 to 3, tpr 0.2 to 30", "ppr 0.2 to 3, tpr 1 to 30", "ppr 1 to 30, tpr 0.2 to 3"]'::jsonb, 0, 'SECTION 30: DAK_RANGE: ppr 0.2 to 30, tpr 1 to 3. Outside it the engine still answers and says so.'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 11, 'IBAFO''s Low bank is run at -80 C. What does gasMassInVessel do?', '["REFUSED: A temperature is required.", "It answers with tpr held at 1, the bottom of DAK_RANGE, so that correlationInRange reads true for the bank.", "It refuses the bank, since tpr 0.9727 lies below the range the correlation was fitted over.", "It answers, with correlationInRange false and a note calling the value an extrapolation."]'::jsonb, 3, 'SECTION 30 prints the probe with tpr 0.9727, correlationInRange false, and the note "Outside the range the Dranchuk-Abou-Kassem correlation was fitted over. The value is an extrapolation and should be checked against measured data." Outside the range the engine still answers.'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 12, 'Which Z method does gasMassInVessel use for massKg?', '["Sutton on Dranchuk-Abou-Kassem pseudo-criticals", "Dranchuk-Abou-Kassem on Sutton pseudo-criticals", "Z taken as one, the ideal gas law", "Dranchuk-Abou-Kassem on the gauge pressure"]'::jsonb, 1, 'SECTION 30: Z by Dranchuk-Abou-Kassem on Sutton pseudo-criticals. Z taken as one is how the engine forms idealMassKg, which it prints beside massKg; the pressures are absolute.'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 13, 'IBAFO''s bank is put to gasMassInVessel with the gas gravity left blank (''''). What does the engine print?', '["REFUSED: A pressure is required.", "The mass on air''s molar mass, the gravity taken as one.", "REFUSED: A gas specific gravity is required.", "REFUSED: A temperature is required."]'::jsonb, 2, 'SECTION 30''s probe table prints "REFUSED: A gas specific gravity is required." for a blank gas gravity. The pressure and temperature refusals are the probes with no pressure and no temperature.'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 14, 'gasMassInVessel prints idealMassKg beside massKg on every bank. What is idealMassKg?', '["The mass at the gauge reading typed as absolute", "The same mass with Z taken as one", "The mass the bank gives up to the cascade", "The mass on the specific gravity alone, M taken as 0.62"]'::jsonb, 1, 'SECTION 30: the ideal mass is the same m = P V M over Z R T with Z taken as one. The gauge reading typed as absolute is its own row of the gauge table, and M is the specific gravity times the molar mass of air.'),
  ('gasvalue', 'advanced', 'module', 'm03-gas-in-a-bank', 15, 'Which massKg and idealMassKg does the engine print for the IBAFO bank at 230 bar(a)?', '["425.6293 kg and 356.2099 kg", "448.1628 kg and 384.7067 kg", "400.5918 kg and 356.2099 kg", "400.5918 kg and 327.7131 kg"]'::jsonb, 3, 'The Low row, 2 m3 at 230 bar(a), prints massKg 400.5918 and idealMassKg 327.7131. 425.6293 kg and 356.2099 kg are the Mid bank''s; 448.1628 kg and 384.7067 kg the High bank''s.'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 1, 'IBAFO''s cascade counts 38 fills and stops. What does it print for hitFillLimit and for the next vehicle?', '["hitFillLimit true; the maxFills cap was reached at 38", "hitFillLimit false; next vehicle reaches 197.7590 bar(a)", "hitFillLimit false; the next vehicle reaches 195.5640 bar(a)", "hitFillLimit true; the next vehicle reaches 197.7590 bar(a)"]'::jsonb, 1, 'SECTION 31 prints hitFillLimit false and nextVehicleReachesBar 197.7590: hitFillLimit reads true only when the count reaches the maxFills cap the call carries, and here it stopped on a vehicle that could not reach its target. 195.5640 bar(a) is the studio''s opening cascade.'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 2, 'What leftInBanksKg does IBAFO''s three-bank cascade print?', '["608.505 kg", "1084.729 kg", "542.689 kg", "665.879 kg"]'::jsonb, 3, 'IBAFO''s cascade prints leftInBanksKg 665.879 and deliveredKg 608.505. 1084.729 kg is left in the same 6.0000 m3 held as one bank at 250 bar(a), and 542.689 kg is the studio''s opening cascade.'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 3, 'The same 6.0000 m3 is held as one bank at 250 bar(a). What does the cascade print?', '["fillsBeforeRecharge 12, cascadeEfficiency 0.1505", "fillsBeforeRecharge 38, cascadeEfficiency 0.4775", "fillsBeforeRecharge 33, cascadeEfficiency 0.4577", "fillsBeforeRecharge 12, cascadeEfficiency 0.4577"]'::jsonb, 0, 'One bank at 250 bar(a) prints 12 fills at cascadeEfficiency 0.1505. The pair 38 and 0.4775 is IBAFO''s three banks, and 33 and 0.4577 the studio''s opening cascade.'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 4, 'At which pressure does IBAFO''s High bank end when the cascade stops?', '["118.3350 bar(a)", "58.9110 bar(a)", "202.6470 bar(a)", "197.7590 bar(a)"]'::jsonb, 2, 'The bank table prints the High bank from 270.0000 to 202.6470, the Mid from 250.0000 to 118.3350 and the Low from 230.0000 to 58.9110. 197.7590 bar(a) is what the next vehicle reaches.'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 5, 'Which banks did the third fill of IBAFO''s cascade draw on?', '["Low", "Low, Mid", "Low, Mid, High", "Mid, High"]'::jsonb, 1, 'The fills table prints Low for fills 1 and 2, Low, Mid for fill 3, and Low, Mid, High for fills 37 and 38.'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 6, 'In what order does a vehicle draw on IBAFO''s banks, by the engine''s note?', '["It draws on the High bank first, then the Mid, then the Low, until it reaches its target pressure.", "It takes an equal share from each bank at once until it reaches its target.", "It empties the Low bank to the 25 bar(a) of its tank before it draws on the Mid.", "It equalises with the lowest bank above it, then the next bank up, until it reaches its target."]'::jsonb, 3, 'The note: "Each vehicle equalises with the lowest bank above it, then the next bank up, until it reaches its target. A bank delivers only while its pressure exceeds the vehicle tank." The Low bank ends at 58.9110 bar(a).'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 7, 'What does the digest say of the heat of a fast fill in the cascade?', '["It is not modelled; the count is a ceiling in that one respect.", "It is modelled, and it brings the count down from 38 fills to 33.", "It is taken from the Facilities compression engine''s discharge.", "It raises the count, so 38 is a floor."]'::jsonb, 0, 'SECTION 31: both engine and oracle are isothermal: the heat of a fast fill is not modelled, so a real fill settles lower and the count is a ceiling in that one respect. 33 is the studio''s opening cascade.'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 8, 'Which storedKg does IBAFO''s cascade print, and what does the digest print beside it?', '["608.505 kg, the same as the Low, Mid and High bank masses summed", "665.879 kg, the same as the Low, Mid and High bank masses summed", "1084.729 kg, the same as the Low, Mid and High bank masses summed", "1274.384 kg, the same as the Low, Mid and High bank masses summed"]'::jsonb, 3, 'The cascade table prints storedKg 1274.384 and, beside it, the Low, Mid and High bank masses summed (SECTION 30) as 1274.384. storedKg minus deliveredKg minus leftInBanksKg prints 0.000.'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 9, 'What does cngCompression do with the Facilities compression engine?', '["It reimplements that engine''s staging in the station''s own metric units.", "It converts units to and from the field units that engine speaks, and calls it.", "It computes the polytropic head itself and hands only the Z on to that engine.", "It checks that engine''s thermodynamics by an oracle of its own."]'::jsonb, 1, 'SECTION 32: cngCompression does not compute compression itself. It converts the station''s metric inputs to the field units the Facilities compression engine speaks, calls it, and converts the answer back. Its basis reads that it converts units and does not reimplement the thermodynamics, and SECTION 32 says the thermodynamics belong to the Facilities course.'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 10, 'For IBAFO''s 400 kg/h of gas 0.62 with suction at 5 bar(a), what does the bridge print?', '["qMMscfd 0.4473 and a suction of 72.5189 psia", "qMMscfd 72.5189 and a suction of 0.4473 psia", "qMMscfd 0.4473 and a suction of 5.0000 psia", "qMMscfd 0.4473 and a suction of 13.3620 psia"]'::jsonb, 0, 'The bridge table prints qMMscfd 0.4473 (the throughput as standard volume) and suction 72.5189 psia. 5.0000 is the stage 1 suction in bar(a), and 13.3620 bar(a) is stage 1''s discharge.'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 11, 'How many stages does the Facilities engine return for IBAFO''s compressor, and at what ratio each?', '["3 stages, each at 2.6723", "4 stages, each at 13.3620", "2 stages, each at 35.7070", "4 stages, each at 2.6723"]'::jsonb, 3, 'SECTION 32 prints stageCount 4 and a ratio of 2.6723 on every stage, from 5.0000 to 255.0000 bar(a). 13.3620 and 35.7070 are stage discharge pressures in bar(a).'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 12, 'cngCompression is given a discharge below its suction. What does it print?', '["REFUSED: A start and a higher target pressure are required.", "REFUSED: A throughput is required.", "REFUSED: A suction pressure and a higher discharge pressure are required.", "A train with a single stage whose ratio is below one."]'::jsonb, 2, 'SECTION 32''s probe table prints this refusal for discharge below suction. The start and target refusal is the cascade''s (SECTION 31); the throughput refusal is the probe with no throughput.'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 13, 'IBAFO''s forecourt takes 14 buses an hour at 6 minutes a fill. What average wait does it give on 3 dispensers?', '["5.7647 minutes", "0.5765 minutes", "0.7588 minutes", "0.2024 minutes"]'::jsonb, 2, 'SECTION 33 prints averageWaitMinutes 5.7647 on 2 dispensers and 0.7588 on 3. 0.5765 and 0.2024 are the probabilityOfWaiting on 2 and on 3.'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 14, 'IBAFO''s forecourt is run at 25 buses an hour on 2 dispensers. What does cngDispensing return?', '["REFUSED: The number of bays must be a whole number, one or more.", "An average wait that grows with the 1.2500 utilisation", "An answer: stable false and utilisation 1.2500", "REFUSED: Arrivals, fill time and a dispenser count are required and must be positive."]'::jsonb, 2, 'SECTION 33: at 25 buses an hour on 2 dispensers the engine gives an answer and no refusal: stable false, utilisation 1.2500, and the message that no average waiting time exists.'),
  ('gasvalue', 'advanced', 'module', 'm04-the-cascade', 15, 'cngDispensing is asked for 2.5 dispensers. What comes back?', '["The queue on 2 dispensers, with 2.5 rounded down to a whole number of bays.", "REFUSED: The number of bays must be a whole number, one or more.", "The queue on 3 dispensers, with 2.5 rounded to the nearest whole bay.", "A queue on 2.5 dispensers, the count taken exactly as it was typed."]'::jsonb, 1, 'SECTION 33''s probe table prints "REFUSED: The number of bays must be a whole number, one or more." for 2.5 dispensers.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 1, 'No CNG consumption is measured for the Lagos bus. What consumption on CNG does conversionEconomics use, and from what source?', '["9.5 kg per 100 km, as measured", "11.6667 kg per 100 km, derived from energy equivalence", "10.1449 kg per 100 km, derived from energy equivalence", "9.3333 kg per 100 km, derived from energy equivalence"]'::jsonb, 2, 'SECTION 34 prints consumptionSource derived from energy equivalence and newFuelConsumptionPer100Km 10.1449 kg at the efficiency ratio of 0.92. 11.6667 kg is the ratio of 0.8 and 9.3333 kg the ratio of 1; 9.5 kg is the measured consumption of the separate probe.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 2, 'How does the engine derive the CNG consumption when none is measured?', '["PMS consumption times PMS energy, over CNG energy times the efficiency ratio", "PMS consumption times CNG energy, over PMS energy times the efficiency ratio", "PMS consumption times PMS energy times the efficiency ratio, over CNG energy", "PMS consumption over the efficiency ratio, on the litres of PMS"]'::jsonb, 0, 'SECTION 34 prints the check row PMS consumption x PMS energy over (CNG energy x efficiency ratio) as 10.1449, the same as newFuelConsumptionPer100Km.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 3, 'What cost per kilometre on CNG does the engine print for the Lagos bus?', '["109.2000 naira", "38.5507 naira", "69.5584 naira", "10.1449 naira"]'::jsonb, 1, 'SECTION 34 prints CNG cost per km 38.5507 and PMS cost per km 109.2000; savingPerKm is 69.5584. 10.1449 is the CNG consumption in kg per 100 km.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 4, 'At the efficiency ratio of 0.92, what annualSaving after maintenance does the engine give?', '["3507666.6700 naira", "3995333.3300 naira", "6006000.0000 naira", "3825710.1400 naira"]'::jsonb, 3, 'SECTION 34 prints annualSaving (after maintenance) 3825710.1400. 3507666.6700 is the ratio of 0.8 and 3995333.3300 the ratio of 1; 6006000.0000 is the PMS cost a year.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 5, 'At the efficiency ratio of 0.92, what simple payback does conversionEconomics print?', '["0.3421 years", "0.3004 years", "0.3137 years", "0.3030 years"]'::jsonb, 2, 'SECTION 34 prints simplePaybackYears 0.3137, and the check row conversion cost over annualSaving as 0.3137. 0.3421 is the ratio of 0.8, 0.3004 the ratio of 1, and 0.3030 the measured consumption of 9.5 kg per 100 km.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 6, 'A measured CNG consumption of 9.5 kg per 100 km is given to the engine. What does it do?', '["It uses it: consumptionSource as measured, simplePaybackYears 0.3030", "It derives 10.1449 kg from energy equivalence and sets the 9.5 aside", "It uses it: consumptionSource as measured, simplePaybackYears 0.3137", "It keeps the derived consumptionSource, with payback 0.3030"]'::jsonb, 0, 'SECTION 34: with a measured CNG consumption of 9.5 kg per 100 km the engine uses it: consumptionSource "as measured", simplePaybackYears 0.3030. 0.3137 is the payback on the derived consumption.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 7, 'CNG is priced at 1100 naira a kg for the same bus. What does conversionEconomics return?', '["annualSaving 3825710.1400 and simplePaybackYears 0.3137", "annualSaving -191681.1600 and a simplePaybackYears of 0.3137", "annualSaving -191681.1600, with simplePaybackYears null", "REFUSED: Annual distance, base consumption and both fuel prices are required."]'::jsonb, 2, 'SECTION 34: with CNG at 1100 naira a kg there is no saving: annualSaving -191681.1600, simplePaybackYears null, and the note "The conversion does not save money at these prices, so there is no payback to report."'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 8, 'What does conversionEconomics print as its paybackNote?', '["Simple payback is discounted at the case''s own stated rate, and the cash flow is handed on already discounted.", "Simple payback is undiscounted. Anything needing a discount rate belongs in the sanctioned economics engine.", "The conversion does not save money at these prices, so there is no payback to report.", "Simple payback is undiscounted, and it is taken from the fuel cost alone, before maintenance."]'::jsonb, 1, 'SECTION 34 prints the paybackNote verbatim. The no saving sentence is the note at 1100 naira a kg; annualSaving is printed after maintenance.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 9, 'What annual cash flow does conversionEconomics hand on for the Lagos bus?', '["year0 -1200000.0000, recurring 3825710.1400", "year0 -1200000.0000, recurring 2120289.8600", "year0 -1200000.0000, recurring 6006000.0000", "year0 -1200000.0000, recurring 3995333.3300"]'::jsonb, 0, 'SECTION 34 prints annualCashFlow year0 -1200000.0000 and recurring 3825710.1400. 2120289.8600 is the CNG cost a year, 6006000.0000 the PMS cost a year, and 3995333.3300 the annualSaving at an efficiency ratio of 1.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 10, 'No measured CNG consumption is given and the efficiency ratio is left blank. What does the engine print?', '["A consumption derived at an efficiency ratio of 1, 9.3333 kg per 100 km", "A consumption derived at the 0.92 ratio, 10.1449 kg per 100 km", "REFUSED: Either a measured consumption on the new fuel, or both fuels'' energy content and an efficiency ratio, are required.", "REFUSED: Annual distance, base consumption and both fuel prices are required."]'::jsonb, 2, 'SECTION 34''s probe table prints this refusal, which ends "Neither is assumed." The other refusal is the probe with no annual distance.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 11, 'Beside the saving, the switch prints a yearly figure in kg of CO2e avoided. Which is it?', '["5579.7100", "7700.0000", "3825710.1400", "2365.8000"]'::jsonb, 3, 'SECTION 34 prints kgCo2eAvoidedPerYear 2365.8000, on the illustrative emission factors 2.3 kg CO2e a litre of PMS and 2.75 a kg of CNG. 5579.7100 is the CNG kg a year, 7700.0000 the PMS litres a year, and 3825710.1400 the annualSaving.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 12, 'What does the efficiency ratio of 0.92 state for the converted bus?', '["CNG carries 0.92 times the energy of PMS for each unit of fuel bought.", "It turns CNG energy into distance 0.92 times as well as PMS energy.", "It covers 0.92 of its 55000 km a year on CNG, and the rest of it on PMS.", "CNG costs 0.92 times as much as PMS for each MJ it supplies."]'::jsonb, 1, 'SECTION 34: the converted engine turns CNG energy into distance 0.92 times as well as PMS energy. The energy contents are typed separately, 32 MJ a litre of PMS and 48 MJ a kg of CNG.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 13, 'IBAFO''s trailers run 4 trips a day with spares 0.1. What does assetFloat print as inCirculation, sparesAllowance and fleetRequired?', '["7.2000, 0.0800 and 8", "7.2000, 0.7200 and 8", "1.8000, 0.7200 and 8", "7.2000, 0.7200 and 0.0800"]'::jsonb, 1, 'SECTION 29 prints IBAFO''s trailers as inCirculation 7.2000, sparesAllowance 0.7200 and fleetRequired 8, the fleet being the ceiling of the assets in circulation plus the spares allowance. 1.8000 is cycleDays and 0.0800 is spareCapacityUnits, what the ceiling adds.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 14, 'IBAFO''s trailer cycle runs Loading, Run out, On station and Run back. Which one does the engine flag as dominant, with its share?', '["Run out and Run back, 0.1667", "On station, 0.5556", "Loading, 0.1111", "At the customer, 0.8421"]'::jsonb, 1, 'On station takes 1 of the 1.8000 days, printed as 0.5556, and the engine names it dominantStage. Loading prints 0.1111 and each run 0.1667. 0.8421 belongs to KANO''s cylinders at the customer.'),
  ('gasvalue', 'advanced', 'module', 'm05-the-customers-switch', 15, 'IBAFO''s trailers print spareCapacityUnits 0.0800. What does the digest call that field?', '["The spares allowance of the fleet", "The spares fraction typed for the trailers", "The share of the cycle spent loading", "What the ceiling adds"]'::jsonb, 3, 'SECTION 29 labels spareCapacityUnits "what the ceiling adds". The spares allowance prints 0.7200, the spares fraction typed is 0.1, and Loading''s share of the cycle is 0.1111.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 1, 'What does SECTION 35 hold about the flare efficiencies?', '["They default to the rule''s tiered values unless a study types its own.", "They have no default; the rule''s tiered defaults are a United States rule.", "They default to the combustion efficiency typed for the case.", "They are pinned and not validated, beside the DAK and Sutton coefficients."]'::jsonb, 1, 'SECTION 35, held: the flare efficiencies have no default: the rule''s tiered defaults are a United States rule, and the basis for a Nigerian study is a regulation reading. The pinned list names heating values, densities, latent heats, the DAK and Sutton coefficients, the rule''s equation form and water at 15 C.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 2, 'SECTION 35 names water at 15 C for a filling density. In which of its lists does it place that item?', '["Among the held limits, as a code value the site types", "Among the case inputs, typed with the GWP values", "Among the checks the oracles make against measured water", "Among the items pinned and not validated"]'::jsonb, 3, 'SECTION 35''s pinned list ends with water at 15 C for a filling density. The held limits are the flare efficiencies, the unlit flare, fill limits by code, and GWP values and credit prices as case inputs.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 3, 'Which fill limit does lpgCng ship for an LPG vessel?', '["None; the site types the limit with its basis.", "0.85 on liquid_volume, KANO''s first limit", "0.42 on water_capacity_mass, the NFPA 58 value", "The NUPRC practice value, on liquid_volume"]'::jsonb, 0, 'SECTION 35, held: fill limits by code (NFPA 58, EN or NUPRC practice) are not shipped: the limit is a safety code value, typed by the site with its basis. SECTION 26 calls 0.85 and 0.42 two illustrative fill limits, neither a code value.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 4, 'What does SECTION 35 say of GWP values and credit prices?', '["They ship in a table, one row per edition.", "They are pinned and not validated.", "They are case inputs.", "They are checked by the validation oracles."]'::jsonb, 2, 'SECTION 35, held: GWP values and credit prices are case inputs. They appear in neither the pinned list nor the list of what the oracles check.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 5, 'Which of these does SECTION 35 list as pinned and not validated?', '["The cascade''s mass ledger", "The DAK and Sutton coefficients", "Erlang C on the positions wholly working", "The ledgers for the blend, storage and vaporizer"]'::jsonb, 1, 'SECTION 35''s pinned list: the component heating values and liquid densities, the typical LPG densities and latent heats, the DAK and Sutton coefficients, the form of the rule''s equations, and water at 15 C for a filling density. The cascade ledger, Erlang C and the blend, storage and vaporizer ledgers are what the oracles check.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 6, 'What do the validation oracles check of cngCompression?', '["The polytropic head of each stage, in exact rationals.", "The four stage ratios, by bisection on reduced density.", "Nothing; the compressor sits on the pinned and not validated list.", "Only the unit bridge; the train''s thermodynamics are validated in Facilities."]'::jsonb, 3, 'SECTION 35: the compressor train''s thermodynamics are the Facilities engine''s and are validated there; only the unit bridge is checked here. The pinned list does not name the compressor, and bisection on reduced density is how the oracle finds Z.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 7, 'How does the oracle find Z, independently of the engine?', '["By bisection on reduced density, with a second correlation as a plausibility check", "By the engine''s own DAK iteration, rerun to four decimals and compared", "As a mass ledger, with conservation asserted on every bank", "In exact rationals, in kilograms and cubic metres"]'::jsonb, 0, 'SECTION 35: Z by bisection on reduced density with a second correlation as a plausibility check. The mass ledger with conservation asserted is the cascade''s check, and exact rationals in kilograms and cubic metres are how the oracle takes the gas.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 8, 'The Kano and Ibafo rollout prints KANO cylinders required. Which figure is it?', '["91200.0000, the cylinders in circulation alone", "3200, the cylinders filled in a day", "98496, the fleet with its 0.08 spares", "7296.0000, the spares allowance alone"]'::jsonb, 2, 'SECTION 36 prints KANO cylinders required 98496, SECTION 29''s fleetRequired. inCirculation prints 91200.0000 and sparesAllowance 7296.0000; 3200 is the cylinders filled a day.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 9, 'Two rollout steps size KANO''s stock: usable LPG and cover. Which pair does the end-to-end table show?', '["62.9433 t and 7.8680 days", "71.0685 t and 8.8836 days", "127.5000 t and 8.8840 days", "71.0685 t and 8.8840 days"]'::jsonb, 3, 'SECTION 36 prints KANO usable LPG at a 0.85 liquid fill 71.0685 t and cover 8.8840 days. 62.9433 t and 7.8680 days are the 0.42 water_capacity_mass row; 8.8836 is usableTonnes over demand before the engine''s three decimal cover; 127.5000 is usableM3 in m3.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 10, 'The rollout''s KANO vaporizer design duty of 98.6948 kW runs on which latent heat?', '["399.0000 kJ/kg, the blend''s on the volume fractions", "397.7592 kJ/kg, the blend''s on mass", "385 kJ/kg, n-butane''s typical row", "425 kJ/kg, propane''s typical row"]'::jsonb, 1, 'The vaporizer in SECTION 27 is fed the latent heat the blend gives on mass, 397.7592 kJ/kg. 399.0000 kJ/kg is the volume-fraction average SECTION 25 sets beside it, and 385 and 425 kJ/kg are the two component rows.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 11, 'Which liquid density does KANO''s vessel run on in the rollout?', '["557.4000 kg/m3, the blend''s on volume", "999.1 kg/m3, the water capacity''s", "584 kg/m3, n-butane''s typical row", "553.6000 kg/m3, the studio opening blend''s"]'::jsonb, 0, 'The rollout''s first step is KANO blend density, 557.4000 kg/m3, which is the liquid density the vessel rows are sized on. 999.1 kg/m3 is WATER_KG_M3; 584 kg/m3 is one component''s typical density, and 553.6000 kg/m3 is a different blend.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 12, 'IBAFO''s forecourt prints kgPerHour 224.1860. Which mass per fill does it carry?', '["425.6293 kg, the Mid bank''s mass", "608.505 kg, the cascade''s deliveredKg", "16.0133 kg, the cascade''s kgPerFill", "10.1449 kg, the bus''s CNG per 100 km"]'::jsonb, 2, 'SECTION 33: IBAFO''s forecourt is 14 buses an hour, 6 minutes a fill, each fill the cascade''s 16.0133 kg. 425.6293 kg is the Mid bank in SECTION 30, 608.505 kg the cascade''s deliveredKg, and 10.1449 kg the bus''s newFuelConsumptionPer100Km.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 13, 'Which gas do IBAFO''s cascade and its banks both run on?', '["Specific gravity 0.6 at 15 C", "Specific gravity 0.62 at 32 C", "Specific gravity 0.62 at -80 C", "Specific gravity 0.62 at 30 C"]'::jsonb, 3, 'SECTIONS 30 and 31 give IBAFO''s gas as specific gravity 0.62 at 30 C. 0.6 at 15 C is the studio''s opening cascade; 32 C is the compressor''s suction temperature; -80 C is the out of range probe on the Low bank.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 14, 'How do the oracles check the cascade?', '["As a mass ledger, with conservation asserted", "In exact rationals, on the positions wholly working", "By bisection on reduced density", "They do not; the cascade is pinned and not validated"]'::jsonb, 0, 'SECTION 35: the cascade as a mass ledger with conservation asserted. Exact rationals on the positions wholly working is the oracle''s Erlang C, and bisection on reduced density its Z. SECTION 31 prints storedKg minus deliveredKg minus leftInBanksKg as 0.000.'),
  ('gasvalue', 'advanced', 'module', 'm06-the-expert-reading', 15, 'Which carousel figures does the rollout print for KANO?', '["17 positions wholly working, an average wait of 0.0450 minutes", "16 positions wholly working, an average wait of 0.0912 minutes", "18 positions wholly working, an average wait of 0.0222 minutes", "14 positions wholly working, an average wait of 0.9850 minutes"]'::jsonb, 1, 'SECTION 36 prints KANO carousel positions wholly working 16 and average wait 0.0912 minutes. 17 and 18 positions are SECTION 28''s whole positions run at availability 1, and 14 positions with 0.9850 minutes is the studio''s opening carousel.'),
  ('gasvalue', 'advanced', 'final', null, 1, 'What typical boiling point does LPG_REFERENCE print for propane?', '["-0.5 C", "38 C", "18 C", "-42 C"]'::jsonb, 3, 'LPG_REFERENCE prints propane''s typical boiling point as -42 C and n-butane''s as -0.5 C. 38 C is the boiling point at KANO''s vaporizer pressure and 18 C the liquid''s inlet temperature (SECTION 27).'),
  ('gasvalue', 'advanced', 'final', null, 2, 'By the engine''s note on LPG_REFERENCE, what is the authority for liquid density, latent heat and calorific value?', '["The certificate of quality", "The typical row in LPG_REFERENCE", "The range printed beside each typical figure", "The site''s code value, typed with its basis"]'::jsonb, 0, 'The note: "Typical values only, offered as a starting point. Liquid density, latent heat and calorific value vary with the product and the supplier; the certificate of quality is the authority."'),
  ('gasvalue', 'advanced', 'final', null, 3, 'The studio opens on propane 0.4 and butane 0.6 by liquid volume. What density does lpgBlendProperties return?', '["557.4000 kg/m3", "553.6000 kg/m3", "508 kg/m3", "999.1 kg/m3"]'::jsonb, 1, 'SECTION 25 prints the studio opening blend at densityKgM3 553.6000 (volume). 557.4000 kg/m3 is KANO''s blend, 508 kg/m3 propane''s typical row, and 999.1 kg/m3 is WATER_KG_M3 (SECTION 26).'),
  ('gasvalue', 'advanced', 'final', null, 4, 'lpgBlendProperties is given a negative volume fraction. Which line comes back?', '["REFUSED: Every component needs a volume fraction.", "REFUSED: A volume fraction cannot be negative.", "A blend taken on the components whose fractions are positive.", "REFUSED: The maximum fill ratio must lie between 0 and 1."]'::jsonb, 1, 'SECTION 25''s probe table prints "REFUSED: A volume fraction cannot be negative." A blank butane volume fraction gets "Every component needs a volume fraction."; the fill ratio refusal belongs to lpgStorageSizing.'),
  ('gasvalue', 'advanced', 'final', null, 5, 'KANO''s vessel is given a fill limit of 1. What does lpgStorageSizing print?', '["REFUSED: At this density the filling density fills the vessel liquid-full.", "The vessel sized liquid-full, with no vapour space left.", "REFUSED: A maximum fill ratio is required and is not defaulted.", "REFUSED: The maximum fill ratio must lie between 0 and 1."]'::jsonb, 3, 'SECTION 26''s probe table prints "REFUSED: The maximum fill ratio must lie between 0 and 1." for a fill limit of 1. The liquid-full refusal is the probe with a filling density of 0.6 on water capacity; the not defaulted refusal is a blank fill limit.'),
  ('gasvalue', 'advanced', 'final', null, 6, 'The fill ratio basis is typed as ''weight''. What does the engine do?', '["It reads weight as water_capacity_mass and names that basis in its output.", "It takes liquid_volume, the basis it takes when none is given in the call.", "REFUSED: Unknown fill ratio basis \"weight\". Use liquid_volume or water_capacity_mass.", "REFUSED: A liquid density is required; it is not assumed."]'::jsonb, 2, 'SECTION 26''s probe table prints the unknown basis refusal for ''weight''. liquid_volume is what the engine takes when the basis is OMITTED from the call; a basis that is typed and unknown is refused.'),
  ('gasvalue', 'advanced', 'final', null, 7, 'What deliveriesPerMonth does lpgStorageSizing print for KANO, and by which rule?', '["12.0000, the demand times 30 over the delivery", "12.0000, usableTonnes over the delivery of 20 t", "8.8840, usableTonnes over the demand", "40.0000, the demand times the lead time plus the safety stock"]'::jsonb, 0, 'SECTION 26: deliveriesPerMonth is the demand times 30 over the delivery, and both rows print 12.0000. usableTonnes over the demand is coverDays, 8.8840 at the 0.85 fill; the demand times the lead time plus the safety stock is reorderAtTonnes, 40.0000.'),
  ('gasvalue', 'advanced', 'final', null, 8, 'The call for KANO''s vessel at 0.85 leaves the lead time field out altogether. Which pair comes back?', '["lead time in missingInputs, reorderAtTonnes null", "missingInputs none, reorderAtTonnes 16.0000", "missingInputs none, reorderAtTonnes 40.0000", "lead time in missingInputs, reorderAtTonnes 16.0000"]'::jsonb, 1, 'Left out of the call, the lead time takes the stated 0 (SECTION 26): no missing inputs, and a reorder point of 16.0000, the safety stock alone. Typed blank (''''), the lead time is named missing and the reorder point is null; 40.0000 belongs to the 3 day lead time.'),
  ('gasvalue', 'advanced', 'final', null, 9, 'KANO''s 0.42 is read as a share of the liquid volume, on the basis it was not stated on. What does the digest print?', '["62.9433 t, the same as on water capacity", "71.0685 t, the 0.85 liquid_volume figure", "27.8271 t, which is 35.1162 t below the 62.9433 t", "35.1162 t, which is 27.8271 t below the 62.9433 t"]'::jsonb, 3, 'Read on the liquid volume, the 0.42 gives 35.1162 t, and the digest prints that as 27.8271 t below the 62.9433 t the filling density gives. 71.0685 t is the 0.85 limit''s usable stock.'),
  ('gasvalue', 'advanced', 'final', null, 10, 'How does vaporizerDuty form the term Warm the liquid to boiling?', '["Mass flow times vapour heat capacity times (outlet less boiling point)", "Mass flow times liquid heat capacity times (outlet less inlet)", "Mass flow times liquid heat capacity times (boiling point less inlet)", "Mass flow times the latent heat"]'::jsonb, 2, 'SECTION 27: warm the liquid is the mass flow times the liquid heat capacity times (boiling point less inlet). The vapour heat capacity term is the superheat and the latent heat term is the boil.'),
  ('gasvalue', 'advanced', 'final', null, 11, 'What does KANO''s Superheat the vapour term print?', '["8.8472 kW, 0.1031 of the duty", "5.1567 kW, 0.1031 of the duty", "71.8176 kW, 0.0601 of the duty", "5.1567 kW, 0.0601 of the duty"]'::jsonb, 3, 'The superheat row reads 5.1567 kW and 0.0601. The 0.1031 share and 8.8472 kW belong to warming the liquid to boiling, and 71.8176 kW to the boil.'),
  ('gasvalue', 'advanced', 'final', null, 12, 'KANO''s vaporizer is given a vapour outlet of 30 C against a boiling point of 38 C. What comes back?', '["REFUSED: The vapour leaves at 30 C, below the boiling point given (38 C), so it would condense.", "A superheat term printed below zero, with the duty reduced by it.", "dutyKW 71.8176, the boil alone, with superheat named as missing.", "REFUSED: The liquid enters at 18 C, above the boiling point given (-0.5 C)."]'::jsonb, 0, 'The outlet probe is refused with a line that ends by asking for an outlet above the boiling point at the vaporizer''s pressure. A blank boiling point is the case that returns the boil alone, and the -0.5 C boiling point is the inlet probe.'),
  ('gasvalue', 'advanced', 'final', null, 13, 'KANO''s vaporizer is run with no latent heat. What does vaporizerDuty print?', '["A duty on n-butane''s typical latent heat of 385 kJ/kg from LPG_REFERENCE.", "The warming and superheat terms, with the boil named as a missing term.", "A duty on the blend''s latent heat of 397.7592 kJ/kg, taken by default.", "REFUSED: A latent heat of vaporisation is required; it is a property of the product and is not assumed."]'::jsonb, 3, 'SECTION 27''s probe table prints the latent heat refusal. A latent heat is a property of the product, and the engine assumes none.'),
  ('gasvalue', 'advanced', 'final', null, 14, 'What arrivalsPerHour does the carousel print for KANO''s 3200 cylinders over a 10 hour shift?', '["320.0000 cylinders an hour", "4516.3600 cylinders an hour", "3200 cylinders an hour", "11.7333 cylinders an hour"]'::jsonb, 0, 'SECTION 28 prints arrivalsPerHour 320.0000. 4516.3600 is throughputCapacityPerDay, 3200 the cylinders a shift, and 11.7333 the queue''s offered load in erlangs.'),
  ('gasvalue', 'advanced', 'final', null, 15, 'What does KANO''s carousel print for minimumPositionsForThroughput and meetsDemand?', '["13 and true", "16 and true", "17 and true", "13 and false"]'::jsonb, 0, 'SECTION 28 prints minimumPositionsForThroughput 13 and meetsDemand true. 16 is queuePositions; 17 is the positions rounded to the nearest whole one, the shortcut the engine does not take.'),
  ('gasvalue', 'advanced', 'final', null, 16, 'On its 16 working positions, what probabilityOfWaiting does KANO''s carousel print?', '["0.1078", "0.0633", "0.1769", "0.7333"]'::jsonb, 2, 'SECTION 28 prints queue probabilityOfWaiting 0.1769. 0.1078 and 0.0633 are the carousel run at availability 1 on 17 and on 18 positions; 0.7333 is the queue utilisation.'),
  ('gasvalue', 'advanced', 'final', null, 17, 'The studio''s opening carousel runs 16 positions at availability 0.9 for 8 hours. What does it print?', '["effectivePositions 14.4000, queuePositions 14", "effectivePositions 14.4000, queuePositions 15", "effectivePositions 16.5600, queuePositions 16", "effectivePositions 14, queuePositions 14.4000"]'::jsonb, 0, 'SECTION 28: the studio''s opening carousel prints effectivePositions 14.4000, queuePositions 14 and averageWaitMinutes 0.9850. 16.5600 and 16 are KANO''s.'),
  ('gasvalue', 'advanced', 'final', null, 18, 'KANO''s carousel is sized with no fill time. Which line comes back?', '["REFUSED: Arrivals, fill time and a dispenser count are required and must be positive.", "REFUSED: Shift hours must be positive and availability must lie in (0, 1].", "A carousel run on the studio''s 2.5 minutes a cylinder.", "REFUSED: Demand, fill time and a position count are required and must be positive."]'::jsonb, 3, 'SECTION 28''s probe table prints the demand, fill time and position count refusal. The arrivals and dispenser count refusal is cngDispensing''s (SECTION 33).'),
  ('gasvalue', 'advanced', 'final', null, 19, 'By Little''s Law, KANO''s 3200 cylinders a day over a 28.5000 day cycle are held in circulation. Which figure does assetFloat print for them?', '["91200.0000", "98496", "7296.0000", "28.5000"]'::jsonb, 0, 'The basis sentence is "Little''s Law: assets in the system = throughput x time in the system." and the KANO table prints inCirculation 91200.0000. 98496 is the fleet after the spares and the ceiling, 7296.0000 the spares allowance, and 28.5000 the cycle in days.'),
  ('gasvalue', 'advanced', 'final', null, 20, 'A cylinder float is asked for with an empty list of cycle stages. The engine''s answer?', '["REFUSED: No duration for At the customer.", "A fleet of none, since no stage holds an asset.", "REFUSED: At least one cycle stage with a duration is required.", "REFUSED: The spares allowance cannot be negative."]'::jsonb, 2, 'SECTION 29''s probe table prints the at least one stage refusal for no stages. "No duration for At the customer." is KANO''s cycle with that stage left blank.'),
  ('gasvalue', 'advanced', 'final', null, 21, 'Which bank of IBAFO''s gas storage holds 448.1628 kg?', '["Mid, 2 m3 at 250 bar(a)", "High, 2 m3 at 270 bar(a)", "Low, 2 m3 at 230 bar(a)", "Mid, read at 250.0130 bar(a)"]'::jsonb, 1, 'SECTION 30 prints massKg 448.1628 on the High row. The Mid bank holds 425.6293 kg, the Low bank 400.5918 kg, and 250.0130 bar(a) gives 425.6447 kg.'),
  ('gasvalue', 'advanced', 'final', null, 22, 'For the 249 bar gauge reading, what does the absolute minus gauge-as-absolute row print?', '["1.0130 bar(a) and 425.6447 kg", "250.0130 bar(a) and 1.2054 kg", "1.0130 bar(a) and 1.2054 kg", "249 bar(a) and 424.4393 kg"]'::jsonb, 2, 'SECTION 30''s gauge table prints absolute minus gauge-as-absolute as 1.0130 bar(a) and 1.2054 kg. 249 and 424.4393 kg are the gauge reading typed as if absolute; 250.0130 and 425.6447 kg are gauge plus atmosphere.'),
  ('gasvalue', 'advanced', 'final', null, 23, 'The bank mass is requested without any pressure. What is printed?', '["REFUSED: A pressure is required.", "REFUSED: A gas specific gravity is required.", "The mass at the atmosphere of 1.013 bar(a).", "REFUSED: A temperature is required."]'::jsonb, 0, 'gasMassInVessel refuses a missing pressure with that line (SECTION 30). 1.013 bar(a) is the site''s atmosphere in SECTION 30''s gauge example.'),
  ('gasvalue', 'advanced', 'final', null, 24, 'Which ppr does IBAFO''s Low bank print at 30 C, and is the correlation in range?', '["ppr 4.9479, correlationInRange true", "ppr 4.9479, correlationInRange false", "ppr 5.8084, correlationInRange true", "ppr 0.9727, correlationInRange false"]'::jsonb, 0, 'SECTION 30''s bank table prints the Low bank at ppr 4.9479 with correlationInRange true. 5.8084 is the High bank''s ppr, and 0.9727 is the tpr of the Low bank at -80 C, where correlationInRange is false.'),
  ('gasvalue', 'advanced', 'final', null, 25, 'Which startBar and endBar does the cascade''s bank table print for the Low bank?', '["250.0000 and 118.3350", "270.0000 and 202.6470", "230.0000 and 58.9110", "230.0000 and 118.3350"]'::jsonb, 2, 'The Low bank runs from 230.0000 to 58.9110 bar(a). The Mid bank''s pair is 250.0000 and 118.3350, and the High bank''s 270.0000 and 202.6470.'),
  ('gasvalue', 'advanced', 'final', null, 26, 'cascadeEfficiency is a ratio of two cascade masses. Which two, and at what value for IBAFO?', '["Delivered over stored, 0.1505", "Left in the banks over stored, 0.4775", "Delivered over stored, 0.4775", "Delivered over stored, 0.4577"]'::jsonb, 2, 'SECTION 31 prints cascadeEfficiency (delivered over stored) 0.4775 for IBAFO. 0.1505 is the same 6.0000 m3 as one bank, and 0.4577 the studio''s opening cascade.'),
  ('gasvalue', 'advanced', 'final', null, 27, 'The studio''s opening cascade, three 1.5 m3 banks at 250 bar(a), prints how many fills before recharge?', '["33, with the next vehicle reaching 195.5640 bar(a)", "38, with the next vehicle reaching 197.7590 bar(a)", "33, with the next vehicle reaching 197.7590 bar(a)", "38, with the next vehicle reaching 195.5640 bar(a)"]'::jsonb, 0, 'SECTION 31: the studio''s opening cascade prints fillsBeforeRecharge 33, cascadeEfficiency 0.4577, leftInBanksKg 542.689 and nextVehicleReachesBar 195.5640. 38 and 197.7590 are IBAFO''s.'),
  ('gasvalue', 'advanced', 'final', null, 28, 'cascadeFills is given a target pressure below the start. What does it print?', '["REFUSED: At least one bank is required.", "REFUSED: A start and a higher target pressure are required.", "REFUSED: A temperature is required.", "A count of no fills, with hitFillLimit false."]'::jsonb, 1, 'A target below the start is refused with the start and higher target line (SECTION 31). The bank refusal is for a call with no banks, and the temperature refusal for a temperature left blank.'),
  ('gasvalue', 'advanced', 'final', null, 29, 'One of IBAFO''s banks is given a volume and no pressure. What does cascadeFills print?', '["REFUSED: A pressure is required.", "REFUSED: Every bank needs a volume and a pressure.", "REFUSED: At least one bank is required.", "A cascade run on the other two banks alone."]'::jsonb, 1, 'SECTION 31''s probe table prints "REFUSED: Every bank needs a volume and a pressure." for a bank with no pressure. "A pressure is required." is gasMassInVessel''s line (SECTION 30).'),
  ('gasvalue', 'advanced', 'final', null, 30, 'Where does IBAFO''s stageCount of 4 come from?', '["cngCompression''s own staging rule on bar(a)", "A stage count typed with IBAFO''s compressor inputs", "The Facilities compression engine that cngCompression calls", "The ratio of 255 to 5 bar(a), taken to a whole number"]'::jsonb, 2, 'SECTION 32''s basis reads: "Staging, polytropic head and real-gas Z from the Facilities compression engine; this converts units and does not reimplement the thermodynamics." The staging is the Facilities engine''s: cngCompression converts IBAFO''s 400 kg/h, suction 5 bar(a) at 32 C and discharge 255 bar(a) to field units, calls that engine and converts the answer back.'),
  ('gasvalue', 'advanced', 'final', null, 31, 'Which stage of IBAFO''s compressor runs from 35.7070 to 95.4220 bar(a)?', '["Stage 2", "Stage 3", "Stage 4", "Stage 1"]'::jsonb, 1, 'SECTION 32''s stage table: stage 1 runs 5.0000 to 13.3620, stage 2 13.3620 to 35.7070, stage 3 35.7070 to 95.4220 and stage 4 95.4220 to 255.0000, each at a ratio of 2.6723.'),
  ('gasvalue', 'advanced', 'final', null, 32, 'The station compressor bridge gets a suction and a discharge but no throughput. Result?', '["REFUSED: A suction pressure and a higher discharge pressure are required.", "REFUSED: A throughput is required.", "REFUSED: A pressure is required.", "A bridge with qMMscfd 0.4473 taken as the default."]'::jsonb, 1, 'SECTION 32''s probe table prints "REFUSED: A throughput is required." for no throughput. 0.4473 is IBAFO''s qMMscfd for its 400 kg/h, and the pressure refusal is gasMassInVessel''s.'),
  ('gasvalue', 'advanced', 'final', null, 33, 'How busy are IBAFO''s two dispensers at 14 buses an hour, as the engine''s utilisation?', '["0.4667", "1.2500", "0.7000", "0.5765"]'::jsonb, 2, 'SECTION 33 prints utilisation 0.7000 on 2 dispensers and 0.4667 on 3. 1.2500 is 25 buses an hour on 2 dispensers, and 0.5765 the probabilityOfWaiting on 2.'),
  ('gasvalue', 'advanced', 'final', null, 34, 'What does cngDispensing''s note say about a forecourt?', '["A CNG fill takes seconds, so a forecourt queues only at traffic a liquid-fuel operator would call heavy.", "A forecourt is a different queue from the carousel and the loading rack, and is sized on its own rule.", "A CNG fill takes minutes, so a forecourt queues at traffic a liquid-fuel operator would think of as quiet.", "A forecourt queues only once its utilisation reaches 1.2500, and never below it."]'::jsonb, 2, 'SECTION 33 prints the note verbatim, and states that a CNG forecourt is the same queue as the carousel and the loading rack. 1.2500 is the utilisation of the overloaded forecourt, and the queues on 2 and 3 dispensers at 14 buses an hour both print a probability of waiting.'),
  ('gasvalue', 'advanced', 'final', null, 35, 'At 25 buses an hour on 2 dispensers, what does the queue''s message say of the average wait?', '["It is 5.7647 minutes, as at 14 buses an hour.", "No average waiting time exists.", "It is the 6 minutes of one fill.", "It is 1.2500 times the fill time."]'::jsonb, 1, 'The message: "The rack cannot keep up with arrivals. The queue grows without limit, so no average waiting time exists. Add a bay, load faster, or spread the arrivals."'),
  ('gasvalue', 'advanced', 'final', null, 36, 'Two dispensers serve IBAFO''s 14 buses an hour. How likely is a bus to wait, by the engine?', '["0.2024", "0.7000", "0.1769", "0.5765"]'::jsonb, 3, 'SECTION 33 prints probabilityOfWaiting 0.5765 on 2 dispensers and 0.2024 on 3; 0.7000 is the utilisation on 2. 0.1769 is KANO''s carousel (SECTION 28).'),
  ('gasvalue', 'advanced', 'final', null, 37, 'What CNG kg a year and CNG cost a year does the Lagos bus switch print?', '["7700.0000 kg and 2120289.8600 naira", "5579.7100 kg and 2120289.8600 naira", "5579.7100 kg and 6006000.0000 naira", "2365.8000 kg and 2120289.8600 naira"]'::jsonb, 1, 'SECTION 34 prints CNG kg a year 5579.7100 and CNG cost a year 2120289.8600. 7700.0000 is the PMS litres a year, 6006000.0000 the PMS cost a year, and 2365.8000 kgCo2eAvoidedPerYear.'),
  ('gasvalue', 'advanced', 'final', null, 38, 'Per kilometre, how much does the Lagos bus save by switching, by the engine?', '["38.5507", "109.2000", "10.1449", "69.5584"]'::jsonb, 3, 'savingPerKm reads 69.5584. A kilometre on PMS costs 109.2000 and on CNG 38.5507; 10.1449 is newFuelConsumptionPer100Km in kg.'),
  ('gasvalue', 'advanced', 'final', null, 39, 'The switch economics are run without the bus''s yearly kilometres. Which line does the engine print?', '["REFUSED: Annual distance, base consumption and both fuel prices are required.", "REFUSED: Either a measured consumption on the new fuel, or both fuels'' energy content and an efficiency ratio, are required.", "A saving per km, with the annual figures left null.", "REFUSED: A throughput is required."]'::jsonb, 0, 'SECTION 34''s probe table prints the annual distance refusal. The either or refusal is the probe with no measured consumption and a blank efficiency ratio.'),
  ('gasvalue', 'advanced', 'final', null, 40, 'The converted bus is assumed to use CNG energy exactly as well as PMS energy, a ratio of 1. Which consumption and payback does the switch print?', '["10.1449 kg per 100 km, payback 0.3137 years", "11.6667 kg per 100 km, payback 0.3421 years", "9.3333 kg per 100 km, payback 0.3030 years", "9.3333 kg per 100 km, payback 0.3004 years"]'::jsonb, 3, 'SECTION 34''s ratio table prints 9.3333 and 0.3004 at a ratio of 1, 10.1449 and 0.3137 at 0.92, and 11.6667 and 0.3421 at 0.8. 0.3030 is the payback on the measured 9.5 kg per 100 km.'),
  ('gasvalue', 'advanced', 'final', null, 41, 'Which of these is a HELD limit in SECTION 35?', '["The DAK and Sutton coefficients are validated by the oracle.", "The compressor''s thermodynamics are checked by this course''s oracle.", "The flare efficiencies default to the rule''s tiers.", "Fill limits by code are not shipped."]'::jsonb, 3, 'SECTION 35 holds four limits: the flare efficiencies have no default, an unlit flare is not modelled, fill limits by code are not shipped, and GWP values and credit prices are case inputs. The DAK and Sutton coefficients are pinned and not validated, and the compressor''s thermodynamics are validated in Facilities.'),
  ('gasvalue', 'advanced', 'final', null, 42, 'The end-to-end table closes on IBAFO. Which three of its figures appear there?', '["Mid bank 425.6447 kg, 38 fills before recharge, 8 trailers", "Mid bank 425.6293 kg, 38 fills before recharge, 8 trailers", "Mid bank 425.6293 kg, 12 fills before recharge, 8 trailers", "Mid bank 425.6293 kg, 38 fills before recharge, 7.2000 trailers"]'::jsonb, 1, 'SECTION 36 prints IBAFO Mid bank 425.6293 kg, fills before recharge 38 and trailers required 8. 425.6447 kg is the gauge plus atmosphere reading, 12 fills the one bank case, and 7.2000 the trailers in circulation.');
